#include <stdio.h>

/* teste do desafio soma-em-funcao — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   A funcao do aluno devolve um valor: o teste monta a caixa, chama com o
   tamanho e confere o retorno — sem captura de saida. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
int somaEmFuncao(int v[], int n);

SM_TEST(a_soma_de_cinco_notas) {
    int notas[5] = {7, 8, 6, 9, 10};
    checa_int("a soma das cinco notas", somaEmFuncao(notas, 5), 40,
              "7 + 8 + 6 + 9 + 10 da 40: todas as gavetas entram na conta");
}

SM_TEST(a_soma_de_uma_lista_menor) {
    int valores[2] = {3, 4};
    checa_int("a soma de uma lista de dois", somaEmFuncao(valores, 2), 7,
              "a mesma funcao serve para qualquer tamanho: 3 + 4 da 7");
}

SM_TEST(o_n_manda_no_laco) {
    int valores[4] = {5, 5, 5, 5};
    checa_int("o laco para no n, nao no fim da caixa", somaEmFuncao(valores, 2), 10,
              "com n igual a 2 so as duas primeiras gavetas entram: 5 + 5 da 10");
}

solutionCode:
int somaEmFuncao(int v[], int n) {
    int soma = 0;
    for (int i = 0; i < n; i++) {
        soma = soma + v[i];
    }
    return soma;
}
